int partition(int p, int r) {
    int x = arr[r];

    int i = p;
    for (int j = p; j < r; j++) {
        if (arr[j] <= x) {
            swap(arr[i], arr[j]);
            i++;
        }
    }

    swap(arr[i], arr[r]);

    return i;
}

void quicksort(int p, int r) {
    if (p == r) return;

    int q = partition(p, r);
    quicksort(p, q - 1);
    quicksort(q + 1, r);
}

