#include <bits/stdc++.h>
using namespace std;

vector<int> a;
long long sum = 0;
int n, p, q, r, s;

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin >> n;

    a.resize(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        sum += a[i];
    }

    cin >> p >> q >> r >> s;

    sort(a.begin(), a.end());

    int st = 1, en = a.back() + 1;
    while (st < en) {
        int mid = (st + en) / 2;

        int sub = a.end() - upper_bound(a.begin(), a.end(), mid + r);
        int add = lower_bound(a.begin(), a.end(), mid) - a.begin();

        if (s <= sum - sub * p + add * q) {
            en = mid;
        } else {
            st = mid + 1;
        }
    }

    if (en == a.back() + 1) cout << -1;
    else cout << st;

    return 0;
}

